mapper.select:
select h.adjustment_hist_id as "adjustmentHistId", h.target_user_id as "targetUserId", case when k.name is not null then k.name else u.login_id end as "targetUserName", h.evaluation_year as "evaluationYear", h.area_code as "areaCode", h.area_name as "areaName", h.management_item_code as "managementItemCode", h.adjustment_target as "adjustmentTarget", h.before_value as "beforeValue", h.after_value as "afterValue", h.adjustment_reason as "adjustmentReason", h.adjustment_remark as "adjustmentRemark", case when adj_k.name is not null then adj_k.name else adjusted_user.login_id end as "adjustedByName", case when appr_k.name is not null then appr_k.name else approved_user.login_id end as "approvedByName", h.adjusted_at as "adjustedAt", h.approved_at as "approvedAt", h.approval_trace as "approvalTrace", h.request_id as "requestId", '점수 조정 이력은 조회 전용이며 점수나 평가백분율 조정 기능을 제공하지 않습니다.' as "readOnlyNotice" from biz_score_adj_hist h join users u on u.user_id = h.target_user_id left join korus_personnel_snapshots k on k.employee_no = u.employee_no left join users adjusted_user on adjusted_user.user_id = h.adjusted_by left join korus_personnel_snapshots adj_k on adj_k.employee_no = adjusted_user.employee_no left join users approved_user on approved_user.user_id = h.approved_by left join korus_personnel_snapshots appr_k on appr_k.employee_no = approved_user.employee_no where h.adjustment_hist_id = #{adjustmentHistId}
and h.organization_code = #{organizationCode}
limit 1
